begin;
create temp table f(owner_id uuid default gen_random_uuid(),viewer_id uuid default gen_random_uuid(),other_id uuid default gen_random_uuid(),company uuid default gen_random_uuid(),other_company uuid default gen_random_uuid(),candidate uuid default gen_random_uuid(),second uuid default gen_random_uuid(),foreigncandidate uuid default gen_random_uuid(),document uuid default gen_random_uuid(),job uuid default gen_random_uuid(),run uuid default gen_random_uuid(),report uuid default gen_random_uuid(),batch uuid default gen_random_uuid(),resume_job uuid default gen_random_uuid(),token uuid default gen_random_uuid(),request uuid default gen_random_uuid());
insert into f default values;
grant select on f to authenticated,service_role;
create temp table results(name text,passed boolean);
grant insert,select on results to authenticated,service_role,anon;
create function pg_temp.ok(n text,b boolean) returns void language plpgsql as $$begin if b is distinct from true then raise exception 'FAILED: %',n;end if;insert into results values(n,true);end$$;
create function pg_temp.denied(n text,s text,e text default null) returns void language plpgsql as $$begin begin execute s;exception when others then if e is not null and sqlstate<>e then raise exception 'FAILED %: % (%)',n,sqlerrm,sqlstate;end if;insert into results values(n,true);return;end;raise exception 'FAILED allowed: %',n;end$$;
insert into auth.users(id,email,role,aud) select id,id::text||'@privacy.invalid','authenticated','authenticated' from f,lateral unnest(array[owner_id,viewer_id,other_id]) id;
insert into public.companies(id,name) select company,'Privacy A' from f union all select other_company,'Privacy B' from f;
insert into public.company_members(company_id,user_id,role) select company,owner_id,'owner' from f union all select company,viewer_id,'viewer' from f union all select other_company,other_id,'owner' from f;
insert into public.candidates(id,company_id,nome,processing_status) select candidate,company,'Pessoa sintética','concluido' from f union all select second,company,'Pessoa preservada','concluido' from f union all select foreigncandidate,other_company,'Outra empresa','concluido' from f;
insert into public.resume_batches(id,company_id,uploaded_by,source,file_count) select batch,company,owner_id,'selecao_local',1 from f;
insert into public.resume_documents(id,company_id,candidate_id,sha256,filename,mime_type,byte_size,page_count,source,state) select document,company,candidate,repeat('a',64),'sintetico.pdf','application/pdf',100,1,'selecao_local','completed' from f;
update public.candidates set active_document_id=(select document from f) where id=(select candidate from f);
insert into public.resume_batch_items select batch,0,document from f;
insert into public.resume_batch_entries(batch_id,slot,filename,state) select batch,0,'sintetico.pdf','received' from f;
insert into public.resume_jobs(id,company_id,document_id,candidate_id,requested_by,request_id,generation,state,attempts,lease_token,lease_until) select resume_job,company,document,candidate,owner_id,gen_random_uuid(),1,'running',1,token,now()+interval '2 minutes' from f;
insert into public.resume_job_attempts(job_id,attempt,extraction) select resume_job,1,'{"nome":"dado sensível de teste"}'::jsonb from f;
insert into public.jobs(id,company_id,titulo) select job,company,'Teste de privacidade' from f;
insert into public.ranking_runs(id,company_id,job_id,request_id,job_snapshot,status) select run,company,job,gen_random_uuid(),'{}','completed' from f;
insert into public.ranking_entries(company_id,run_id,candidate_id,snapshot,documents) select company,run,candidate,'{"name":"sintético"}'::jsonb,'[]'::jsonb from f union all select company,run,second,'{}','[]' from f;
insert into public.vacancy_reports(id,company_id,job_id,run_id,candidate_ids,request_id,payload) select report,company,job,run,array[candidate,second],gen_random_uuid(),'{}' from f;
insert into public.vacancy_report_events(company_id,report_id,action) select company,report,'generated' from f;
insert into public.job_reports(company_id,job_id,conteudo) select company,job,'{"snapshot":"sintético"}' from f;
insert into storage.objects(bucket_id,name) select 'resumes',object_path from public.resume_documents where id=(select document from f);
select set_config('request.jwt.claims',json_build_object('sub',owner_id,'role','authenticated')::text,true) from f;
set local role authenticated;
select public.set_candidate_job_link(company,candidate,job,true) from f;
select public.save_candidate_decision(company,candidate,job,0,'em_analise',false,'Conferência sintética',gen_random_uuid()) from f;
select public.add_candidate_note(company,candidate,job,'Nota sintética privada',gen_random_uuid()) from f;
select set_config('test.case',public.save_privacy_request(company,candidate,'export','protocolo-sintetico',now()+interval '1 day')::text,true) from f;
select pg_temp.denied('export requires verified identity',$q$select public.export_privacy_subject(company,current_setting('test.case')::uuid) from f$q$,'42501');
select public.save_privacy_request(company,candidate,'export','protocolo-sintetico',now()+interval '1 day',current_setting('test.case')::uuid,0,'verified','conferencia-interna') from f;
select pg_temp.ok('subject export audited and scoped',public.export_privacy_subject(company,current_setting('test.case')::uuid)->'candidate'->>'id'=candidate::text) from f;
select pg_temp.ok('export audit caller',(select count(*)=1 from public.privacy_events where action='subject_export_requested' and actor_id=(select owner_id from f)));
select pg_temp.denied('stale case version rejected',$q$select public.save_privacy_request(company,candidate,'export','protocolo-sintetico',now(),current_setting('test.case')::uuid,0,'completed','verificacao','entrega registrada') from f$q$,'40001');
select set_config('test.hold',public.set_privacy_hold(company,candidate,'Necessidade sintética para revisão administrativa.',now()+interval '2 days')::text,true) from f;
select pg_temp.ok('preview reports active hold',(public.preview_candidate_erasure(company,candidate)->>'holds')::integer=1) from f;
select pg_temp.denied('active hold blocks erasure',$q$select public.request_candidate_erasure(company,candidate,array[candidate],'Pedido sintético de eliminação',request) from f$q$);
select public.set_privacy_hold(company,candidate,'Justificativa sintética para liberação.',now(),current_setting('test.hold')::uuid) from f;
select pg_temp.denied('cross company erasure preview',$q$select public.preview_candidate_erasure(company,foreigncandidate) from f$q$,'42501');
select pg_temp.denied('scope must match preview',$q$select public.request_candidate_erasure(company,candidate,array[candidate,second],'Pedido sintético de eliminação',request) from f$q$,'40001');
select pg_temp.denied('cannot forge erasure progress',$q$update public.privacy_erasure_operations set state='completed'$q$,'42501');
select pg_temp.denied('client cannot call worker',$q$select public.claim_privacy_erasure()$q$,'42501');
select set_config('request.jwt.claims',json_build_object('sub',viewer_id,'role','authenticated')::text,true) from f;
select pg_temp.ok('viewer cannot read privacy requests',(select count(*)=0 from public.privacy_requests));
select pg_temp.denied('viewer cannot request erasure',$q$select public.request_candidate_erasure(company,candidate,array[candidate],'Pedido sintético de eliminação',request) from f$q$,'42501');
select set_config('request.jwt.claims',json_build_object('sub',owner_id,'role','authenticated')::text,true) from f;
select set_config('test.op',public.request_candidate_erasure(company,candidate,array[candidate],'Pedido sintético de eliminação',request)::text,true) from f;
select pg_temp.ok('request idempotent',public.request_candidate_erasure(company,candidate,array[candidate],'Pedido sintético de eliminação',request)=current_setting('test.op')::uuid) from f;
select pg_temp.ok('new request reuses existing erasure',public.request_candidate_erasure(company,candidate,array[candidate],'Outra solicitação sintética',gen_random_uuid())=current_setting('test.op')::uuid) from f;
select pg_temp.ok('candidate immediately hidden',(select count(*)=0 from public.candidates where id=(select candidate from f)));
select pg_temp.ok('original immediately hidden',(select count(*)=0 from storage.objects where name like (select company::text||'/%' from f)));
select pg_temp.ok('shared report immediately inaccessible',(select count(*)=0 from public.vacancy_reports where id=(select report from f)));
select pg_temp.denied('new extraction conflicts with erasure',$q$select public.request_document_analysis(company,document,gen_random_uuid()) from f$q$);
select pg_temp.denied('export blocked during erasure',$q$select public.export_privacy_subject(company,current_setting('test.case')::uuid) from f$q$);
select pg_temp.denied('new hold after irreversible request blocked',$q$select public.set_privacy_hold(company,candidate,'Retenção que chegou depois do pedido.',now()+interval '1 day') from f$q$);
set local role service_role;
select pg_temp.ok('existing file survives request',(select count(*)=1 from storage.objects where name=(select object_path from public.resume_documents where id=(select document from f))));
select pg_temp.ok('running lease is drained',(select available_at>now()+interval '2 minutes' from public.privacy_erasure_operations where id=current_setting('test.op')::uuid));
select pg_temp.ok('late extraction cannot resurrect',not public.settle_resume_job(resume_job,token,'succeeded','{"nome_completo":"ressuscitado"}')) from f;
select pg_temp.ok('scheduler waits for drain',public.claim_privacy_erasure() is null);
update public.privacy_erasure_operations set available_at=now()-interval '1 minute' where id=current_setting('test.op')::uuid;
-- Inject a transient database fault: the subtransaction must roll back, preserving file.
reset role;
create function pg_temp.fail_purge() returns trigger language plpgsql as $$begin raise exception 'injected DB failure';end$$;
create trigger privacy_test_failure before delete on public.candidates for each statement execute function pg_temp.fail_purge();
set local role service_role;
select pg_temp.ok('failed DB purge yields no storage targets',public.claim_privacy_erasure() is null);
select pg_temp.ok('failure state persisted',(select state='queued' and last_error is not null and attempts=1 from public.privacy_erasure_operations where id=current_setting('test.op')::uuid));
select pg_temp.ok('DB data preserved after failed purge',(select count(*)=1 from public.resume_documents where id=(select document from f)));
select pg_temp.ok('file preserved after failed purge',(select count(*)=1 from storage.objects where name=(select object_path from public.resume_documents where id=(select document from f))));
reset role;
drop trigger privacy_test_failure on public.candidates;
set local role service_role;
update public.privacy_erasure_operations set available_at=now()-interval '1 minute' where id=current_setting('test.op')::uuid;
select set_config('test.claim',public.claim_privacy_erasure()::text,true);
select pg_temp.ok('purge commits before Storage remove',(select state='files_pending' and database_purged_at is not null from public.privacy_erasure_operations where id=current_setting('test.op')::uuid));
select pg_temp.ok('candidate erased',(select count(*)=0 from public.candidates where id=(select candidate from f)));
select pg_temp.ok('other candidates preserved',(select count(*)=2 from public.candidates where id in(select second from f union all select foreigncandidate from f)));
select pg_temp.ok('document versions and attempts erased',(select count(*)=0 from public.resume_documents where id=(select document from f)) and (select count(*)=0 from public.resume_job_attempts where job_id=(select resume_job from f)));
select pg_temp.ok('notes decisions links removed',(select count(*)=0 from public.candidate_notes where candidate_id=(select candidate from f)) and (select count(*)=0 from public.candidate_decision_events where candidate_id=(select candidate from f)) and (select count(*)=0 from public.candidate_job_links where candidate_id=(select candidate from f)));
select pg_temp.ok('report and audit snapshot purged',(select count(*)=0 from public.vacancy_reports where id=(select report from f)) and (select count(*)=0 from public.vacancy_report_events where report_id=(select report from f)));
select pg_temp.ok('ranking snapshots removed only for target',(select count(*)=1 from public.ranking_entries where run_id=(select run from f)) and (select stale from public.ranking_runs where id=(select run from f)));
select pg_temp.ok('filename manifest removed',(select count(*)=0 from public.resume_batch_entries where batch_id=(select batch from f)));
select pg_temp.ok('cannot complete while storage exists',not public.finish_privacy_erasure(current_setting('test.op')::uuid,(current_setting('test.claim')::jsonb->>'token')::uuid,true));
select pg_temp.ok('storage failure visible',(select state='files_pending' and last_error is not null from public.privacy_erasure_operations where id=current_setting('test.op')::uuid));
update public.privacy_erasure_operations set available_at=now()-interval '1 minute' where id=current_setting('test.op')::uuid;
select set_config('test.claim',public.claim_privacy_erasure()::text,true);
select pg_temp.ok('second concurrent claim cannot take active lease',public.claim_privacy_erasure() is null);
-- Model worker termination AFTER successful Storage removal, BEFORE acknowledgment.
reset role;
delete from storage.objects where bucket_id='resumes' and name=(select company::text||'/'||candidate::text||'/original' from f);
set local role service_role;
update public.privacy_erasure_operations set lease_until=now()-interval '1 minute' where id=current_setting('test.op')::uuid;
select set_config('test.recovered',public.claim_privacy_erasure()::text,true);
select pg_temp.ok('stale worker token rejected',not public.finish_privacy_erasure(current_setting('test.op')::uuid,(current_setting('test.claim')::jsonb->>'token')::uuid,true));
select pg_temp.ok('interrupted deletion completes',public.finish_privacy_erasure(current_setting('test.op')::uuid,(current_setting('test.recovered')::jsonb->>'token')::uuid,true));
select pg_temp.ok('completed state explicit',(select state='completed' and completed_at is not null from public.privacy_erasure_operations where id=current_setting('test.op')::uuid));
select pg_temp.ok('completed operation does not run again',public.claim_privacy_erasure() is null);
select pg_temp.ok('minimal journal survives',(public.export_privacy_ledger()->'erasures'->0->'candidate_ids') @> jsonb_build_array((select candidate from f)));
-- Restore an old logical copy, then reconcile BEFORE reopening the isolated system.
reset role;
insert into public.candidates(id,company_id,nome) select candidate,company,'Dado antigo restaurado' from f;
insert into storage.objects(bucket_id,name) select 'resumes',company::text||'/'||candidate::text||'/original' from f;
set local role service_role;
select public.reconcile_privacy_restore(company,array[candidate]) from f;
select pg_temp.ok('restored grants removed',(select count(*)=0 from public.company_members where company_id=(select company from f)));
select set_config('request.jwt.claims',json_build_object('sub',owner_id,'role','authenticated')::text,true) from f;
set local role authenticated;
select pg_temp.ok('old JWT cannot read restored company',(select count(*)=0 from public.candidates where company_id=(select company from f)));
select pg_temp.denied('old JWT cannot issue export',$q$select public.export_privacy_subject(company,current_setting('test.case')::uuid) from f$q$,'42501');
set local role service_role;
select set_config('test.restored',public.claim_privacy_erasure()::text,true);
select pg_temp.ok('restored erased data purged again',(select count(*)=0 from public.candidates where id=(select candidate from f)));
select pg_temp.ok('restored file scheduled again',jsonb_array_length(current_setting('test.restored')::jsonb->'files')=1);
select * from results;
select count(*) as passed from results;
rollback;
